create table if not exists public.dreem_refund_disbursements(id uuid primary key default gen_random_uuid(),school_id uuid not null,refund_request_id uuid not null unique references public.dreem_refund_requests(id),payment_id uuid not null references public.dreem_financial_payments(id),student_id uuid not null,amount numeric(14,2) not null check(amount>0),method text not null check(method in('cash','momo','bank_transfer','card','cheque')),external_reference text,evidence_reference text not null,paid_by uuid not null default auth.uid(),paid_at timestamptz not null default now(),idempotency_key text not null,unique(school_id,idempotency_key));
create table if not exists public.dreem_refund_allocation_releases(id uuid primary key default gen_random_uuid(),school_id uuid not null,refund_disbursement_id uuid not null references public.dreem_refund_disbursements(id),payment_allocation_id uuid not null references public.dreem_payment_allocations(id),fee_charge_id uuid not null references public.dreem_student_fee_charges(id),amount numeric(14,2) not null check(amount>0),created_at timestamptz not null default now(),unique(refund_disbursement_id,payment_allocation_id));
alter table public.dreem_refund_disbursements enable row level security;alter table public.dreem_refund_allocation_releases enable row level security;revoke all on public.dreem_refund_disbursements,public.dreem_refund_allocation_releases from anon;grant select on public.dreem_refund_disbursements,public.dreem_refund_allocation_releases to authenticated;create policy "finance roles read refund disbursements" on public.dreem_refund_disbursements for select to authenticated using(private.dreem_has_role(school_id,array['leadership','bursar','accountant','auditor']));create policy "finance roles read refund releases" on public.dreem_refund_allocation_releases for select to authenticated using(private.dreem_has_role(school_id,array['leadership','bursar','accountant','auditor']));
create or replace function private.dreem_recalculate_fee_account(p_fee_account_id uuid)returns void language plpgsql security definer set search_path='' as $$declare v_due numeric;v_paid numeric;begin select coalesce(sum(greatest(c.amount-c.waived_amount,0)),0)into v_due from public.dreem_student_fee_charges c where c.fee_account_id=p_fee_account_id and c.status<>'cancelled';select coalesce(sum(a.amount),0)-coalesce((select sum(r.amount)from public.dreem_refund_allocation_releases r join public.dreem_payment_allocations pa on pa.id=r.payment_allocation_id where pa.payment_id in(select p.id from public.dreem_financial_payments p where p.fee_account_id=p_fee_account_id)),0)into v_paid from public.dreem_payment_allocations a join public.dreem_financial_payments p on p.id=a.payment_id where p.fee_account_id=p_fee_account_id;update public.fee_accounts set amount_due=v_due,amount_paid=greatest(v_paid,0),balance_due=greatest(v_due-v_paid,0),status=case when greatest(v_due-v_paid,0)=0 then'settled'else'open'end,updated_at=now()where id=p_fee_account_id;update public.dreem_student_fee_charges c set status=case when greatest(c.amount-c.waived_amount-coalesce((select sum(a.amount)from public.dreem_payment_allocations a where a.fee_charge_id=c.id),0)+coalesce((select sum(r.amount)from public.dreem_refund_allocation_releases r where r.fee_charge_id=c.id),0),0)=0 then'paid'when c.due_on is not null and c.due_on<current_date then'overdue'else'due'end,updated_at=now()where c.fee_account_id=p_fee_account_id and c.status<>'cancelled';end;$$;
create or replace function public.dreem_execute_approved_refund(p_refund_id uuid,p_method text,p_external_reference text,p_evidence_reference text,p_idempotency_key text)returns uuid language plpgsql security definer set search_path='' as $$declare r public.dreem_refund_requests%rowtype;p public.dreem_financial_payments%rowtype;v_id uuid;v_remaining numeric;v_available numeric;v_release numeric;alloc record;begin select * into r from public.dreem_refund_requests where id=p_refund_id;if not found then raise exception 'Refund request not found';end if;if r.status<>'approved'then raise exception 'Refund must be independently approved before payment';end if;if not private.dreem_has_role(r.school_id,array['bursar','leadership'])then raise exception 'Bursar or leadership role required to execute refund';end if;if p_method not in('cash','momo','bank_transfer','card','cheque')then raise exception 'Invalid refund method';end if;if trim(coalesce(p_evidence_reference,''))=''then raise exception 'Refund evidence reference required';end if;select * into p from public.dreem_financial_payments where id=r.payment_id;insert into public.dreem_refund_disbursements(school_id,refund_request_id,payment_id,student_id,amount,method,external_reference,evidence_reference,idempotency_key)values(r.school_id,r.id,r.payment_id,r.student_id,r.amount,p_method,nullif(trim(coalesce(p_external_reference,'')),''),trim(p_evidence_reference),p_idempotency_key)on conflict(school_id,idempotency_key)do update set idempotency_key=excluded.idempotency_key returning id into v_id;v_remaining:=r.amount;for alloc in select a.id,a.fee_charge_id,a.amount-coalesce((select sum(x.amount)from public.dreem_refund_allocation_releases x where x.payment_allocation_id=a.id),0)as available from public.dreem_payment_allocations a where a.payment_id=r.payment_id order by a.created_at desc loop exit when v_remaining<=0;v_available:=greatest(alloc.available,0);if v_available<=0 then continue;end if;v_release:=least(v_available,v_remaining);insert into public.dreem_refund_allocation_releases(school_id,refund_disbursement_id,payment_allocation_id,fee_charge_id,amount)values(r.school_id,v_id,alloc.id,alloc.fee_charge_id,v_release)on conflict(refund_disbursement_id,payment_allocation_id)do nothing;v_remaining:=v_remaining-v_release;end loop;update public.dreem_refund_requests set status='paid',refund_payment_id=null where id=r.id;if p.fee_account_id is not null then perform private.dreem_recalculate_fee_account(p.fee_account_id);end if;insert into public.dreem_finance_journal_entries(school_id,entry_type,reference_type,reference_id,student_id,debit_account,credit_account,amount,description,idempotency_key)values(r.school_id,'refund','refund_disbursement',v_id,r.student_id,'Refunds / fee reversal',case when p_method='cash'then'Cash'else'Bank / digital settlement'end,r.amount,'Approved refund executed against receipt '||p.receipt_number,'refund-journal:'||v_id::text)on conflict(school_id,idempotency_key)do nothing;insert into public.audit_events(school_id,actor_id,action,entity_type,entity_id,detail)values(r.school_id,(select auth.uid()),'finance.refund_paid','refund_disbursement',v_id,jsonb_build_object('refund_request_id',r.id,'payment_id',r.payment_id,'amount',r.amount,'method',p_method,'unallocated_credit_refunded',greatest(v_remaining,0)));return v_id;end;$$;
revoke all on function public.dreem_execute_approved_refund(uuid,text,text,text,text) from public;grant execute on function public.dreem_execute_approved_refund(uuid,text,text,text,text) to authenticated;